/* First visit: follow the visitor's browser language (Arabic, French, otherwise English for
   international visitors). A choice made in the language picker is remembered afterwards. */
function detectLanguage() {
  const preferred = navigator.languages?.length
    ? navigator.languages
    : [navigator.language || "fr"];
  for (const tag of preferred) {
    const base = String(tag).slice(0, 2).toLowerCase();
    if (base === "ar" || base === "fr" || base === "en") return base;
  }
  return "en";
}
let language = (() => {
  try {
    return localStorage.getItem("gj-language") || detectLanguage();
  } catch {
    return detectLanguage();
  }
})();
if (!LANGUAGES[language]) language = "fr";
function t(key) {
  return COPY[key]?.[language] ?? COPY[key]?.fr ?? key;
}
function locale() {
  return { fr: "fr-MA", en: "en-GB", ar: "ar-MA" }[language];
}
